package com.noahprail.kairos.protocol

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.io.File

/** Loads docs/test-vectors.json (generated by the Node reference implementation). */
@Serializable
data class Vectors(
    val framing: List<Framing>,
    val auth: Auth,
    val status: List<Status>,
) {
    @Serializable
    data class Framing(val name: String, val payload: String, val maxFragment: Int, val fragments: List<String>)

    @Serializable
    data class Auth(
        val secretHex: String,
        val nonceB64: String,
        val clientNonceB64: String,
        val clientProofB64: String,
        val serverProofB64: String,
    )

    @Serializable
    data class Status(val hex: String, val expected: Expected) {
        @Serializable
        data class Expected(
            val flags: Int,
            val phase: String,
            val configRev: Long,
            val nextEventAt: Long,
            val nextEventType: String,
            val attemptsRemaining: Int,
        )
    }

    companion object {
        fun load(): Vectors {
            // Gradle runs unit tests from android/app; the vectors live at <repo>/docs.
            var dir: File? = File("").absoluteFile
            while (dir != null && !File(dir, "docs/test-vectors.json").exists()) dir = dir.parentFile
            val file = File(requireNotNull(dir) { "docs/test-vectors.json not found" }, "docs/test-vectors.json")
            return Json { ignoreUnknownKeys = true }.decodeFromString(serializer(), file.readText())
        }
    }
}

fun ByteArray.hex(): String = joinToString("") { "%02x".format(it) }

fun hexBytes(hex: String): ByteArray = ByteArray(hex.length / 2) { hex.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
